//! AASLD public disease-topic indexes and their source-labelled independent publisher links.
use super::{common,Adapter,PlanRow};
use super::pmc_crosswalk::{self as cw,Lookup,SourceRef};
use super::r2b_crosswalk as xw;
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::Fetcher;
use crate::guidelines::html::{blocks_from_html,sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::{json,Value};
use std::collections::HashSet;
use url::Url;
pub struct Aasld;
fn catalog(html:&str,base:&Url)->Result<Vec<(String,String)>>{let d=Html::parse_document(html);let card=d.select(&sel(".content-card")).find(|c|c.select(&sel("h2.content-card__title")).any(|h|text_of(&h)=="Guidelines and Guidance by Disease")).context("AASLD disease catalog missing")?;let mut out=vec![];let mut seen=HashSet::new();for a in card.select(&sel("a[href]")){let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let u=Url::parse(&url)?;if u.origin()!=base.origin()||!u.path().starts_with("/practice-guidelines/"){continue;}let title=text_of(&a);if !title.is_empty()&&seen.insert(url.clone()){out.push((url,title))}}if out.is_empty(){bail!("AASLD disease catalog is empty");}Ok(out)}
fn topic(html:&str,base:&Url)->Result<(String,String,Vec<crate::guidelines::doc::Block>,Vec<Value>)>{let d=Html::parse_document(html);let title=d.select(&sel("#block-aasld-page-title h1")).next().map(|e|text_of(&e)).filter(|x|!x.is_empty()).context("AASLD topic title missing")?;let cards=d.select(&sel("#main-content .rtf")).collect::<Vec<_>>();let mut source=String::from("<div id='aasld-topic'>");let mut links=vec![];
 for (i,c) in cards.iter().enumerate(){let heading=c.select(&sel("h2,h3,h4")).next().map(|e|text_of(&e)).unwrap_or_default();for (j,a) in c.select(&sel("a[href]")).enumerate(){let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let label=text_of(&a);let low=label.to_lowercase();let role=if low.contains("correction")||low.contains("errata"){"correction"}else if low.contains("position paper"){"position_paper"}else if low.contains("critical update"){"critical_update"}else if low.contains("visual brief"){"visual_brief"}else if low.contains("practice guidance"){"practice_guidance"}else if low.contains("guideline"){"practice_guideline"}else if heading.to_lowercase().contains("quality measures"){"quality_measure"}else{"related_resource"};links.push(json!({"doi":stated_doi(&url),"url":url,"label":label,"role":role,"source_heading":heading,"source_locator":format!("card/{i}/link/{j}"),"rights":"unknown; independent publisher or asset"}));}source.push_str(&c.html());}source.push_str("</div>");if links.is_empty(){bail!("AASLD topic has no source-linked assets");}let hash=crate::common::sha256_hex(source.as_bytes());let(blocks,_)=blocks_from_html(&source,Some(base),Some("#aasld-topic"));Ok((title,hash,blocks,links))}
/// DOI exactly as the AASLD link states it (doi.org, journals.lww.com/10.x/…, …/doi/10.x/…); never looked up.
fn stated_doi(url:&str)->Option<String>{let u=Url::parse(url).ok()?;let segs:Vec<&str>=u.path_segments()?.filter(|x|!x.is_empty()).collect();
 if matches!(u.host_str(),Some("doi.org"|"dx.doi.org")){let d=segs.join("/");return d.starts_with("10.").then_some(d)}
 if u.host_str()==Some("journals.lww.com")&&segs.len()>=2&&segs[0].starts_with("10."){return Some(format!("{}/{}",segs[0],segs[1]))}
 let i=segs.iter().position(|x|*x=="doi")?;let parts:Vec<&str>=segs[i+1..].iter().take_while(|x|!x.chars().all(|c|c.is_ascii_digit())).copied().collect();(parts.len()>=2&&parts[0].starts_with("10.")).then(||parts.join("/"))}
const GUIDANCE_ROLES:[&str;4]=["practice_guidance","practice_guideline","critical_update","position_paper"];
fn guideline_dois(links:&[Value])->Value{let mut seen=HashSet::new();Value::Array(links.iter().filter(|l|GUIDANCE_ROLES.contains(&l["role"].as_str().unwrap_or("")))
 .filter_map(|l|{let d=l["doi"].as_str()?.to_string();seen.insert(d.to_lowercase()).then(||json!({"doi":d,"role":l["role"],"label":l["label"],"url":l["url"]}))}).collect())}
fn unresolved(src:&SourceEntry,url:String,e:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("{}-unresolved",common::short_hash(&url)),url,title:None,rendition:Some("html".into()),version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for Aasld{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let cat=f.get_ok(src.catalog_url.as_deref().context("AASLD catalog missing")?).await?;let base=Url::parse(&cat.record.final_url)?;let mut rows=vec![];let mut deferred=vec![];let mut cx=xw::Session::default();for(url,_)in catalog(&cat.text(),&base)?{let page=match f.get_ok(&url).await{Ok(p)=>p,Err(e)=>{deferred.push(unresolved(src,url,format!("{e:#}")));continue;}};let b=Url::parse(&page.record.final_url)?;if b.origin()!=base.origin(){deferred.push(unresolved(src,url,"topic origin changed".into()));continue;}match topic(&page.text(),&b){Ok((title,hash,_,links))=>{let key=common::short_hash(&url);let topic_url=url.clone();let i=rows.len();rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("{key}-{}",&hash[..12]),url,title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"work_key":key,"topic_sha256":hash,"catalog_fetch":cat.record,"guideline_dois":guideline_dois(&links),"oa_route":"pmc_crosswalk"})});
  // Round 2: each stated guidance DOI → its PMC copy (full-text row after the topic row) or a relation-only PMC link on the topic document.
  let source_doc=format!("guideline:{}:{}",src.id,rows[i].doc_key);let mut open=vec![];for d in guideline_dois(&links).as_array().cloned().unwrap_or_default(){let Some(doi)=d["doi"].as_str().and_then(cw::normalize_doi) else {continue};let sref=SourceRef{source_url:d["url"].as_str().unwrap_or_default().into(),evidence_url:Some(topic_url.clone()),source_title:None,item_type:d["role"].as_str().map(String::from),key_prefix:"aasld-pmc".into(),id_route:"source_doi".into(),notes:vec![]};let mut c=cx.try_id(src,f,Lookup::Doi(doi),sref,json!({"aasld_topic":topic_url,"role":d["role"],"source_label":d["label"],"stated_doi":d["doi"]}),Some(source_doc.clone())).await;if let Some(r)=c.row.take(){open.push(r)}xw::record_on(&mut rows[i],&c);}rows.extend(open);},Err(e)=>deferred.push(unresolved(src,url,format!("{e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}let rem=limit.map(|n|n.saturating_sub(rows.len())).unwrap_or(usize::MAX);rows.extend(deferred.into_iter().take(rem));Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if cw::is_crosswalk_row(row){return xw::extract(src,f,row).await}if let Some(e)=row.extra["discovery_error"].as_str(){bail!("AASLD source unresolved: {e}");}let p=f.get_ok(&row.url).await?;let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(&row.url)?.origin(){bail!("AASLD topic origin changed");}let(title,hash,blocks,attachments)=topic(&p.text(),&b)?;if row.extra["topic_sha256"].as_str().is_some_and(|x|x!=hash){bail!("AASLD topic changed since discovery");}let mut fetches=vec![];if let Ok(r)=serde_json::from_value::<crate::guidelines::doc::FetchRecord>(row.extra["catalog_fetch"].clone()){fetches.push(r)}fetches.push(p.record);Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title,url:row.url.clone(),item_type:Some("guideline_topic_index".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("Topic index and each publisher resource have separate unverified rights.".into()),..Default::default()},relations:{let mut r:Vec<crate::guidelines::doc::Relation>=guideline_dois(&attachments).as_array().map(|v|v.iter().map(|d|crate::guidelines::doc::Relation{rel:"related".into(),target:format!("doi:{}",d["doi"].as_str().unwrap_or_default()),scope:d["role"].as_str().map(String::from),evidence_url:Some(row.url.clone())}).collect()).unwrap_or_default();let x=xw::relations_from_extra(&row.extra,&r);r.extend(x);r},search_metadata:json!({"guideline_dois":guideline_dois(&attachments)}),blocks,attachments,fetches,warnings:vec!["Topic index only: linked practice guidance, critical updates, visual briefs and quality measures were not acquired as full clinical documents; publisher gates and rights remain independent.".into()],..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const C:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aasld/catalog.html"));const H:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aasld/hcc-topic.html"));#[test]fn real_hcc_topic_retains_distinct_source_roles(){let base=Url::parse("https://www.aasld.org/practice-guidelines").unwrap();let target="https://www.aasld.org/practice-guidelines/management-hepatocellular-carcinoma";assert!(catalog(C,&base).unwrap().iter().any(|(u,_)|u==target));let(title,_,_,links)=topic(H,&Url::parse(target).unwrap()).unwrap();assert!(title.contains("Hepatocellular"));for role in ["critical_update","practice_guidance","visual_brief","quality_measure"]{assert!(links.iter().any(|v|v["role"]==role));}assert!(links.iter().any(|v|v["url"]=="https://doi.org//10.1097/HEP.0000000000001269"&&v["role"]=="critical_update"));assert!(links.iter().any(|v|v["url"]=="https://doi.org//10.1097/HEP.0000000000000466"&&v["role"]=="practice_guidance"));assert!(!links.iter().any(|v|v["url"].as_str().unwrap_or("").contains("HCC-Guideline-2018.pdf")));assert!(topic("<html/>",&base).is_err());}}
#[cfg(all(test, feature = "guideline-fixtures"))]mod genuine_plain_rtf_tests{use super::*;#[test]fn source_plain_rtf_preserves_intro_position_paper_and_correction(){let html=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aasld/acute-liver.html"));let u=Url::parse("https://www.aasld.org/practice-guidelines/management-acute-liver-failure").unwrap();let(title,_,blocks,links)=topic(html,&u).unwrap();assert_eq!(title,"Management of Acute Liver Failure");assert!(blocks.iter().any(|b|b.text.contains("diagnosis of acute liver failure")&&b.text.contains("encephalopathic")));assert!(links.iter().any(|x|x["role"]=="position_paper"&&x["url"].as_str().unwrap().contains("Introduction_to_the_revised")));assert!(links.iter().any(|x|x["role"]=="correction"&&x["url"].as_str().unwrap().ends_with("ErrataAcuteLiverFailure2011.pdf")));}}
#[cfg(all(test, feature = "guideline-fixtures"))]mod fix_round1_dois{use super::*;
#[test]fn topic_links_carry_only_stated_dois(){let h=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aasld/hcc-topic.html"));let(_,_,_,links)=topic(h,&Url::parse("https://www.aasld.org/practice-guidelines/management-hepatocellular-carcinoma").unwrap()).unwrap();let d=guideline_dois(&links);let v=d.as_array().unwrap();assert!(v.iter().any(|x|x["doi"]=="10.1097/HEP.0000000000000466"&&x["role"]=="practice_guidance"));assert!(v.iter().any(|x|x["doi"]=="10.1097/HEP.0000000000001269"&&x["role"]=="critical_update"));assert!(!v.iter().any(|x|x["role"]=="visual_brief"));
 assert_eq!(stated_doi("https://journals.lww.com/10.1097/HEP.0000000000001549").as_deref(),Some("10.1097/HEP.0000000000001549"));assert_eq!(stated_doi("https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciad319/7179952").as_deref(),Some("10.1093/cid/ciad319"));assert!(stated_doi("https://journals.lww.com/hep/Fulltext/2014/08000/Hepatic_encephalopathy.30.aspx").is_none());}}
#[cfg(all(test, feature = "guideline-fixtures"))]mod fix_round2_crosswalk{use super::*;
/// Stated guidance DOI (hep.32689, DILI) → ID Converter → PMC OAI OA JATS (CC BY-NC) → full-text row after the topic row;
/// the topic document links it and keeps its doi: relation.
#[tokio::test]async fn stated_guidance_doi_gets_pmc_full_text_and_topic_relation(){let fx=|n:&str|std::fs::read(format!("{}/tests/fixtures/guidelines/{n}",env!("CARGO_MANIFEST_DIR"))).unwrap();
 let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,8<<20,"").unwrap();let cat="https://www.aasld.org/practice-guidelines";let topic_url="https://www.aasld.org/practice-guidelines/drug-herbal-and-dietary-supplement-induced-liver-injury";
 f.seed_cache_for_tests(cat,b"<div class='content-card'><h2 class='content-card__title'>Guidelines and Guidance by Disease</h2><a href='/practice-guidelines/drug-herbal-and-dietary-supplement-induced-liver-injury'>DILI</a></div>","text/html");
 f.seed_cache_for_tests(topic_url,&fx("aasld/dili-topic.html"),"text/html");f.seed_cache_for_tests(&cw::idconv_url(&Lookup::Doi("10.1002/hep.32689".into())),&fx("r2b_crosswalk/idconv-aasld-dili.json"),"application/json");f.seed_cache_for_tests(&cw::oai_url("PMC9936988").unwrap(),&fx("r2b_crosswalk/oai-PMC9936988-trimmed.xml"),"text/xml");
 let src:SourceEntry=serde_json::from_value(json!({"id":"aasld","access":"public","enabled":true,"catalog_url":cat})).unwrap();let rows=Aasld.discover(&src,&f,None).await.unwrap();assert_eq!(rows.len(),2);
 assert!(!cw::is_crosswalk_row(&rows[0])&&cw::is_crosswalk_row(&rows[1]));assert!(rows[1].doc_key.starts_with("aasld-pmc-pmc9936988-"));assert_eq!(rows[0].extra["pmc_crosswalk_results"][0]["status"],"full_text");
 let topic=Aasld.extract(&src,&f,&rows[0]).await.unwrap();assert!(topic.relations.iter().any(|r|r.target=="doi:10.1002/hep.32689"));assert!(topic.relations.iter().any(|r|r.target==format!("guideline:aasld:{}",rows[1].doc_key)));
 let d=Aasld.extract(&src,&f,&rows[1]).await.unwrap();assert_eq!(d.rights.status,"open");assert!(d.rights.license.as_deref().unwrap().starts_with("CC-BY-NC"));assert!(d.item_type.as_deref().is_some_and(|x|x.contains("guidance")||x.contains("guideline")),"{:?}",d.item_type);
 assert!(d.relations.iter().any(|r|r.target==format!("guideline:aasld:{}",rows[0].doc_key)));assert!(d.relations.iter().any(|r|r.target=="pmc:PMC9936988"));assert!(d.blocks.len()>20);}
}
